Import ListNotations.
Open Scope Z_scope.
Local Ltac addr_near k ::= let inb := eval vm_compute in (andb (Z.leb 0 k) (Z.ltb k 8192))%Z in lazymatch inb with true => idtac end.   (* [comment removed for export] *)
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.

Ltac showpc := match goal with |- evt _ _ (MS _ _ ?pc _ _ _ _) => idtac "PC:" pc end.

(* [comment removed for export] *)
Definition unreg_got (m : mem) : Prop :=
  ro_cells asegs m 0xfdaf0 [C8 (Z_to_bv 64 0x19c720)]
  /\ ro_cells asegs m 0xfdb00 [C8 (Z_to_bv 64 0x19e7a8); C8 (Z_to_bv 64 0x10a478); C8 (Z_to_bv 64 0x10cc78);
                               C8 (Z_to_bv 64 0x10d968); C8 (Z_to_bv 64 0x10d970); C8 (Z_to_bv 64 0x10d960);
                               C8 (Z_to_bv 64 0xff9e0)].

Definition unreg_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp - 240, bv_unsigned sp); (0x10a530, 0x10a538);
              (XS1_LO, XS1_HI); (XS2_LO, XS2_HI); (XS3_LO, XS3_HI); (0x63f302, 0x63f304); (0x63f300, 0x63f302)] m m'
    /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp).

Lemma unreg_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo : Z) (o1 o2 o3 o4 : byte),
  a0 = Z_to_bv 64 0x102520 -> a1 = Z_to_bv 64 450 ->
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - 240 -> 0x800c0000 <= lo ->
  unreg_got m ->
  ro_cells asegs m 0x10a490 [C4 (Z_to_bv 64 1)] ->
  rw_cells asegs m 0x10a530 [C8 (Z_to_bv 64 0)] ->
  ro_cells asegs m 0x10cc78 [C8 (Z_to_bv 64 0x7fff8000)] ->
  rw_cells asegs m 0x10d958 [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x10c4dc [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x19e820 [C8 (Z_to_bv 64 0xffffffffffffffff)] ->
  ro_cells asegs m 0xff9e0 [C8 (Z_to_bv 64 0xf424c)] ->
  stk asegs m XS1_LO XS1_HI -> stk asegs m XS2_LO XS2_HI -> stk asegs m XS3_LO XS3_HI ->
  gds_at m 0x102520 asan_gds ->
  rw_cells asegs m 0x63f302 [C1 o1] -> rw_cells asegs m 0x63f300 [C1 o2] -> rw_cells asegs m 0x63f301 [C1 o3] -> rw_cells asegs m 0x63f303 [C1 o4] ->
